from collections import defaultdict
from typing import List

class Solution:
    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def count_from(start: int) -> int:
            reached = set()

            def dfs(node: int, dist: int, seen: set[int]) -> None:
                for nxt, weight in graph[node]:
                    new_dist = dist + weight
                    if nxt not in seen and new_dist <= distanceThreshold:
                        reached.add(nxt)
                        seen.add(nxt)
                        dfs(nxt, new_dist, seen)
                        seen.remove(nxt)

            dfs(start, 0, {start})
            return len(reached)

        best_city, best_count = -1, float("inf")
        for city in range(n):
            cnt = count_from(city)
            if cnt <= best_count:
                best_city, best_count = city, cnt
        return best_city

